// Obtener el body completo y el barcode enviado en el webhook
const body = $json.body ?? {};
const barcode = body.barcode;

// --------------------------------------------------
// 1. Solicitud completamente vacía → autodocumentación
// --------------------------------------------------
if (Object.keys(body).length === 0) {
  return {
    ...$json,
    validationOk: false,
    responseCode: 200,
    response: {
      status: "info",
      service: "SnackCheck - Nutrition Verdict",
      message: "Send a product barcode to receive a nutritional verdict.",
      method: "POST",
      endpoint: "/nutrition-check",
      required_field: "barcode",
      example: {
        barcode: "3017620422003"
      }
    }
  };
}

// --------------------------------------------------
// 2. Validación normal del barcode
// --------------------------------------------------

// Array donde iremos guardando todos los errores encontrados
const errors = [];

// Validar que barcode exista y no esté vacío
if (
  barcode === undefined ||
  barcode === null ||
  String(barcode).trim() === ''
) {
  errors.push({
    status: "error",
    code: "INPUT_MISSING_BARCODE",
    message: "The barcode field is required.",
    field: "barcode",

    details: {
      what: "The 'barcode' field is missing or empty.",
      why: "The workflow needs a valid product barcode to retrieve nutritional data.",
      how: "Include a barcode in the request body. Example: {\"barcode\": \"3017620422003\"}"
    },

    timestamp: new Date().toISOString()
  });
}

// Validar que barcode contenga solo números
if (
  barcode !== undefined &&
  barcode !== null &&
  String(barcode).trim() !== '' &&
  !/^\d+$/.test(String(barcode).trim())
) {
  errors.push({
    status: "error",
    code: "INPUT_INVALID_BARCODE",
    message: "The barcode must contain numbers only.",
    field: "barcode",

    details: {
      what: "The provided barcode contains invalid characters.",
      why: "Open Food Facts identifies products using numeric barcodes.",
      how: "Provide the barcode using digits only. Example: {\"barcode\": \"3017620422003\"}"
    },

    timestamp: new Date().toISOString()
  });
}

// --------------------------------------------------
// 3. Si hay errores → validación fallida
// --------------------------------------------------
if (errors.length > 0) {
  return {
    ...$json,
    validationOk: false,
    responseCode: 400,
    response: {
      status: "error",
      errors
    }
  };
}

// --------------------------------------------------
// 4. Si no hubo errores → validación correcta
// --------------------------------------------------
return {
  ...$json,
  validationOk: true,
  barcode: String(barcode).trim()
};

